{
  "name": "tx_slot_state_reset",
  "confidence": "medium",
  "docstring": "Clears and reinitializes a 32-byte TX-slot state entry from a table by index, releasing any pending kernel event lock before setting slot identity, owner/state fields, and returning the slot pointer.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "slot_idx",
    "v1": "state_table",
    "v2": "slot_ptr",
    "v3": "slot_idx_u8",
    "v4": "slot_off",
    "v6": "slot_ptr",
    "result": "slot_ptr",
    "v7": "global_init_value"
  },
  "struct_hints": [
    {
      "offset": 4,
      "meaning": "slot initialization value copied from global dword_12B060, possibly timestamp/event/state id"
    },
    {
      "offset": 8,
      "meaning": "slot self/owner pointer or associated context pointer"
    },
    {
      "offset": 24,
      "meaning": "slot state field initialized to 3"
    },
    {
      "offset": 28,
      "meaning": "slot index stored as a byte"
    },
    {
      "offset": 30,
      "meaning": "lock/event pending flag; if set, ke_event_set_lock is called before the slot is cleared"
    }
  ]
}
